package com.medicare360.doctor; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/doctors") @CrossOrigin(origins="http://localhost:4200") public class DoctorController { private final DoctorRepository repo; public DoctorController(DoctorRepository repo){this.repo=repo;} @GetMapping public List<Doctor> all(){return repo.findAll();} @PostMapping public Doctor create(@RequestBody Doctor d){return repo.save(d);} @PutMapping("/{id}") public Doctor update(@PathVariable Long id,@RequestBody Doctor d){Doctor x=repo.findById(id).orElseThrow();x.setName(d.getName());x.setSpecialization(d.getSpecialization());x.setEmail(d.getEmail());x.setPhone(d.getPhone());return repo.save(x);} @DeleteMapping("/{id}") public void delete(@PathVariable Long id){repo.deleteById(id);} }